   107  void ObjFileImporter::InternReadFile(const std::string &file, aiScene *pScene, IOSystem *pIOHandler) {
   108      // Read file into memory
   109      static const std::string mode = "rb";
   110      std::unique_ptr<IOStream> fileStream(pIOHandler->Open(file, mode));
   111      if (!fileStream.get()) {
   112          throw DeadlyImportError("Failed to open file " + file + ".");
   113      }
   114
   115      // Get the file-size and validate it, throwing an exception when fails
   116      size_t fileSize = fileStream->FileSize();
   117      if (fileSize < ObjMinSize) {
   118          throw DeadlyImportError("OBJ-file is too small.");
   119      }
   120
   121      IOStreamBuffer<char> streamedBuffer;
   122      streamedBuffer.open(fileStream.get());
   123
   124      // Allocate buffer and read file into it
   125      //TextFileToBuffer( fileStream.get(),m_Buffer);
   126
   127      // Get the model name
   128      std::string modelName, folderName;
   129      std::string::size_type pos = file.find_last_of("\\/");
   130      if (pos != std::string::npos) {
   131          modelName = file.substr(pos + 1, file.size() - pos - 1);
   132          folderName = file.substr(0, pos);
   133          if (!folderName.empty()) {
   134              pIOHandler->PushDirectory(folderName);
   135          }
   136      } else {
   137          modelName = file;
   138      }
   139
   140      // parse the file into a temporary representation
   141      ObjFileParser parser(streamedBuffer, modelName, pIOHandler, m_progress, file);
   142
   143      // And create the proper return structures out of it
   144      CreateDataFromImport(parser.GetModel(), pScene);
   145
   146      streamedBuffer.close();
   147
   148      // Clean up allocated storage for the next import
   149      m_Buffer.clear();
   150
   151      // Pop directory stack
   152      if (pIOHandler->StackSize() > 0) {
   153          pIOHandler->PopDirectory();
   154      }
